            EXPECT_EQ(*m_hMissingLen[i], numIndices);
            int64_t missCount = 0;
            m_pCache->performance_metric_get_value(m_perfMetric[i][MERTIC_COUNT_MISSES], &missCount, 0);
            CHECK_CUDA_ERROR(cudaDeviceSynchronize());
